<?php
$today=date('Y-m-d');
$apptQ=db()->prepare("SELECT COUNT(*) FROM appointments WHERE appointment_date=?".(is_therapist()?' AND therapist_id=?':''));$apptQ->execute(is_therapist()?[$today,(int)(current_user()['therapist_id']??0)]:[$today]);$todayAppts=(int)$apptQ->fetchColumn();
$walkQ=db()->prepare("SELECT COUNT(*) FROM appointments WHERE appointment_date=? AND source='walk_in'");$walkQ->execute([$today]);$todayWalkins=(int)$walkQ->fetchColumn();
$doneQ=db()->prepare("SELECT COUNT(*) FROM appointments WHERE appointment_date=? AND status='completed'".(is_therapist()?' AND therapist_id=?':''));$doneQ->execute(is_therapist()?[$today,(int)(current_user()['therapist_id']??0)]:[$today]);$todayDone=(int)$doneQ->fetchColumn();
$pendingQ=db()->prepare("SELECT COUNT(*) FROM appointments WHERE appointment_date=? AND status IN ('pending','confirmed')".(is_therapist()?' AND therapist_id=?':''));$pendingQ->execute(is_therapist()?[$today,(int)(current_user()['therapist_id']??0)]:[$today]);$todayPending=(int)$pendingQ->fetchColumn();
$revQ=db()->prepare("SELECT COALESCE(SUM(total),0) FROM transactions WHERE DATE(created_at)=? AND status='paid'");$revQ->execute([$today]);$todayRevenue=(float)$revQ->fetchColumn();
$therapistCount=(int)db()->query("SELECT COUNT(*) FROM therapists WHERE status='active' AND availability_status='available'")->fetchColumn();
$monthly=(float)db()->query("SELECT COALESCE(SUM(total),0) FROM transactions WHERE status='paid' AND YEAR(created_at)=YEAR(CURDATE()) AND MONTH(created_at)=MONTH(CURDATE())")->fetchColumn();
$expense=(float)db()->query("SELECT COALESCE(SUM(amount),0) FROM expenses WHERE YEAR(expense_date)=YEAR(CURDATE()) AND MONTH(expense_date)=MONTH(CURDATE())")->fetchColumn();
$popular=db()->query("SELECT ti.description, SUM(ti.quantity) qty FROM transaction_items ti JOIN transactions t ON t.id=ti.transaction_id WHERE t.status='paid' AND t.created_at>=DATE_SUB(CURDATE(),INTERVAL 30 DAY) GROUP BY ti.description ORDER BY qty DESC LIMIT 5")->fetchAll();
$recent=db()->query("SELECT t.id,t.transaction_code,t.total,t.payment_method,t.created_at,c.full_name FROM transactions t LEFT JOIN customers c ON c.id=t.customer_id WHERE t.status='paid' ORDER BY t.created_at DESC LIMIT 6")->fetchAll();
$nextSql="SELECT a.*,c.full_name,s.name service_name,th.full_name therapist_name FROM appointments a JOIN customers c ON c.id=a.customer_id JOIN services s ON s.id=a.service_id JOIN therapists th ON th.id=a.therapist_id WHERE a.appointment_date=CURDATE()"; $params=[]; if(is_therapist()){ $nextSql.=' AND a.therapist_id=?'; $params[]=(int)(current_user()['therapist_id']??0); } $nextSql.=' ORDER BY a.start_time LIMIT 8'; $q=db()->prepare($nextSql);$q->execute($params);$upcoming=$q->fetchAll();
$months=[];$sales=[];for($i=5;$i>=0;$i--){$d=new DateTimeImmutable('first day of this month');$d=$d->modify("-$i months");$months[]=$d->format('M');$q=db()->prepare("SELECT COALESCE(SUM(total),0) FROM transactions WHERE status='paid' AND YEAR(created_at)=? AND MONTH(created_at)=?");$q->execute([$d->format('Y'),$d->format('n')]);$sales[]=(float)$q->fetchColumn();} $maxSale=max($sales) ?: 1;
?>
<div class="page-heading"><div><div class="eyebrow">Business overview</div><h1>Good <?=date('H')<12?'morning':(date('H')<18?'afternoon':'evening')?>, <?=h(explode(' ',current_user()['name'])[0])?> 👋</h1><p>Here’s what’s happening at your wellness space today.</p></div><div class="d-flex gap-2"><?php if(is_staff()):?><a href="<?=h(app_page_url('appointments',['new'=>1]))?>" class="btn btn-outline-secondary"><i class="bi bi-calendar-plus me-1"></i> New appointment</a><a href="<?=h(app_page_url('pos'))?>" class="btn btn-primary"><i class="bi bi-plus-lg me-1"></i> New sale</a><?php else:?><a href="<?=h(app_page_url('appointments'))?>" class="btn btn-outline-secondary"><i class="bi bi-calendar-week me-1"></i> My schedule</a><?php endif;?></div></div>
<div class="row g-3 mb-4">
<?php $stats=[['Today’s revenue',money($todayRevenue),'cash-coin','Paid transactions today'],['Appointments',$todayAppts,'calendar3',$todayPending.' pending or confirmed'],['Walk-ins',$todayWalkins,'person-walking','Registered today'],['Completed sessions',$todayDone,'check2-circle','Finished today'],['Available therapists',$therapistCount,'person-check','Marked available']]; if(is_therapist())$stats=[['My appointments',$todayAppts,'calendar3','Assigned to your schedule'],['Completed sessions',$todayDone,'check2-circle','Finished today']]; foreach($stats as $i=>$stat):?><div class="col-6 col-xl"><div class="card stat-card h-100"><div class="d-flex justify-content-between align-items-center"><span class="stat-label"><?=h($stat[0])?></span><span class="stat-icon"><i class="bi bi-<?=h($stat[2])?>"></i></span></div><div class="stat-value <?=($i===0?'text-success':'')?>"><?=h((string)$stat[1])?></div><div class="stat-foot"><?=h($stat[3])?></div></div></div><?php endforeach;?>
</div>
<?php if(is_admin()):?><div class="row g-3 mb-4"><div class="col-xl-8"><div class="card h-100"><div class="card-header d-flex justify-content-between align-items-center"><span>Revenue overview</span><span class="small-muted">Last 6 months</span></div><div class="card-body"><div class="d-flex justify-content-between align-items-start"><div><div class="small-muted">Revenue this month</div><div class="fs-3 fw-bold"><?=money($monthly)?></div><div class="small-muted">Net after recorded expenses: <strong><?=money($monthly-$expense)?></strong></div></div><div class="stat-icon"><i class="bi bi-graph-up-arrow"></i></div></div><div class="chart-bars" aria-label="Monthly revenue chart"><?php foreach($sales as $i=>$sale):?><div class="chart-bar-wrap"><div class="chart-amount"><?=number_format($sale/1000,1)?>k</div><div class="chart-bar" style="height:<?=max(2,($sale/$maxSale)*115)?>px"></div><div class="chart-month"><?=h($months[$i])?></div></div><?php endforeach;?></div></div></div></div><div class="col-xl-4"><div class="card h-100"><div class="card-header">Popular services <span class="small-muted fw-normal">· 30 days</span></div><div class="card-body"><?php if(!$popular):?><div class="empty-state"><i class="bi bi-stars"></i>No service sales yet.</div><?php else: foreach($popular as $i=>$p):?><div class="d-flex justify-content-between align-items-center mb-3"><div class="d-flex gap-2 align-items-center"><span class="queue-number">0<?=$i+1?></span><span class="fw-semibold"><?=h($p['description'])?></span></div><span class="text-muted small"><?=h($p['qty'])?> sold</span></div><?php endforeach;endif;?></div></div></div></div><?php endif;?>
<div class="row g-3"><div class="col-xl-7"><div class="card"><div class="card-header d-flex justify-content-between"><span>Today’s schedule</span><a href="<?=h(app_page_url('appointments'))?>" class="small text-decoration-none">View calendar</a></div><div class="table-responsive"><table class="table"><thead><tr><th>Time</th><th>Customer</th><th>Service</th><th>Therapist</th><th>Status</th></tr></thead><tbody><?php if(!$upcoming) echo table_empty(5,'No appointments scheduled for today.'); foreach($upcoming as $a):?><tr><td class="fw-semibold"><?=date('g:i A',strtotime($a['start_time']))?></td><td><?=h($a['full_name'])?></td><td><?=h($a['service_name'])?></td><td><?=h($a['therapist_name'])?></td><td><?=status_badge($a['status'])?></td></tr><?php endforeach;?></tbody></table></div></div></div><?php if(!is_therapist()):?><div class="col-xl-5"><div class="card"><div class="card-header d-flex justify-content-between"><span>Recent transactions</span><a href="<?=h(app_page_url('transactions'))?>" class="small text-decoration-none">See all</a></div><div class="table-responsive"><table class="table"><thead><tr><th>Transaction</th><th>Customer</th><th>Amount</th></tr></thead><tbody><?php if(!$recent) echo table_empty(3,'No transactions recorded yet.'); foreach($recent as $t):?><tr><td><a class="fw-semibold text-decoration-none" href="<?=h(app_page_url('receipt',['id'=>$t['id']]))?>"><?=h($t['transaction_code'])?></a><div class="small-muted"><?=date('M j, g:i A',strtotime($t['created_at']))?></div></td><td><?=h($t['full_name']??'Walk-in / Guest')?></td><td class="fw-bold"><?=money($t['total'])?></td></tr><?php endforeach;?></tbody></table></div></div></div><?php endif;?></div>
